    File_write_line(f, "        public static PdfStr FromText(string s)");
    File_write_line(f, "        {");
    File_write_line(f, "            bool ascii = true;");
    File_write_line(f, "            foreach (char ch in s) if (ch > 126 || ch < 32) { ascii = false; break; }");
    File_write_line(f, "            if (ascii)");
    File_write_line(f, "            {");
    File_write_line(f, "                StringBuilder sb = new StringBuilder(\"(\");");
