    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        // Decoded text value (PDFDocEncoding treated as Latin-1, or UTF-16BE with BOM)");
    File_write_line(f, "        public string Decode()");
    File_write_line(f, "        {");
    File_write_line(f, "            byte[] b = DecodeBytes();");
    File_write_line(f, "            if (b.Length >= 2 && b[0] == 0xFE && b[1] == 0xFF)");
    File_write_line(f, "                return Encoding.BigEndianUnicode.GetString(b, 2, b.Length - 2);");
    File_write_line(f, "            return Encoding.GetEncoding(28591).GetString(b);");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        public byte[] DecodeBytes()");
    File_write_line(f, "        {");
    File_write_line(f, "            List<byte> o = new List<byte>();");
    File_write_line(f, "            if (Raw.Length > 0 && Raw[0] == '<')");
    File_write_line(f, "            {");
    File_write_line(f, "                int hi = -1;");
    File_write_line(f, "                for (int i = 1; i < Raw.Length - 1; i++)");
    File_write_line(f, "                {");
    File_write_line(f, "                    int v = HexVal(Raw[i]);");
    File_write_line(f, "                    if (v < 0) continue;");
    File_write_line(f, "                    if (hi < 0) hi = v; else { o.Add((byte)(hi * 16 + v)); hi = -1; }");
    File_write_line(f, "                }");
    File_write_line(f, "                if (hi >= 0) o.Add((byte)(hi * 16));");
    File_write_line(f, "                return o.ToArray();");
    File_write_line(f, "            }");
    File_write_line(f, "            for (int i = 1; i < Raw.Length - 1; i++)");
    File_write_line(f, "            {");
    File_write_line(f, "                byte c = Raw[i];");
    File_write_line(f, "                if (c != '\\\\') { o.Add(c); continue; }");
    File_write_line(f, "                i++;");
    File_write_line(f, "                if (i >= Raw.Length - 1) break;");
    File_write_line(f, "                c = Raw[i];");
    File_write_line(f, "                switch ((char)c)");
    File_write_line(f, "                {");
    File_write_line(f, "                    case 'n': o.Add(10); break;");
    File_write_line(f, "                    case 'r': o.Add(13); break;");
    File_write_line(f, "                    case 't': o.Add(9); break;");
    File_write_line(f, "                    case 'b': o.Add(8); break;");
    File_write_line(f, "                    case 'f': o.Add(12); break;");
    File_write_line(f, "                    case '\\r': if (i + 1 < Raw.Length - 1 && Raw[i + 1] == '\\n') i++; break;");
    File_write_line(f, "                    case '\\n': break;");
    File_write_line(f, "                    default:");
    File_write_line(f, "                        if (c >= '0' && c <= '7')");
    File_write_line(f, "                        {");
    File_write_line(f, "                            int v = c - '0'; int n = 1;");
    File_write_line(f, "                            while (n < 3 && i + 1 < Raw.Length - 1 && Raw[i + 1] >= '0' && Raw[i + 1] <= '7') { i++; v = v * 8 + (Raw[i] - '0'); n++; }");
    File_write_line(f, "                            o.Add((byte)v);");
    File_write_line(f, "                        }");
    File_write_line(f, "                        else o.Add(c);");
    File_write_line(f, "                        break;");
    File_write_line(f, "                }");
    File_write_line(f, "            }");
    File_write_line(f, "            return o.ToArray();");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        static int HexVal(byte c)");
    File_write_line(f, "        {");
    File_write_line(f, "            if (c >= '0' && c <= '9') return c - '0';");
    File_write_line(f, "            if (c >= 'a' && c <= 'f') return c - 'a' + 10;");
    File_write_line(f, "            if (c >= 'A' && c <= 'F') return c - 'A' + 10;");
    File_write_line(f, "            return -1;");
    File_write_line(f, "        }");
    File_write_line(f, "    }");
    File_write_line(f, "");
    File_write_line(f, "    public sealed class PdfName : PdfObj");
    File_write_line(f, "    {");
    File_write_line(f, "        public string Raw;   // without the leading '/', #xx escapes kept");
