    File_write_line(f, "    }");
    File_write_line(f, "");
    File_write_line(f, "    public sealed class PdfDict : PdfObj");
    File_write_line(f, "    {");
    File_write_line(f, "        public List<string> Keys = new List<string>();");
    File_write_line(f, "        public Dictionary<string, PdfObj> Map = new Dictionary<string, PdfObj>();");
    File_write_line(f, "");
    File_write_line(f, "        public PdfObj Get(string k)");
    File_write_line(f, "        {");
    File_write_line(f, "            PdfObj v;");
    File_write_line(f, "            return Map.TryGetValue(k, out v) ? v : null;");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        public void Set(string k, PdfObj v)");
    File_write_line(f, "        {");
    File_write_line(f, "            if (!Map.ContainsKey(k)) Keys.Add(k);");
    File_write_line(f, "            Map[k] = v;");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        public void Remove(string k)");
    File_write_line(f, "        {");
    File_write_line(f, "            if (Map.Remove(k)) Keys.Remove(k);");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        public string NameOf(string k)");
    File_write_line(f, "        {");
    File_write_line(f, "            PdfName n = Get(k) as PdfName;");
    File_write_line(f, "            return n == null ? null : n.Raw;");
    File_write_line(f, "        }");
    File_write_line(f, "    }");
    File_write_line(f, "");
    File_write_line(f, "    public sealed class PdfRef : PdfObj");
    File_write_line(f, "    {");
    File_write_line(f, "        public int Num, Gen;");
    File_write_line(f, "        public PdfRef(int n, int g) { Num = n; Gen = g; }");
    File_write_line(f, "    }");
    File_write_line(f, "");
    File_write_line(f, "    public sealed class PdfStream : PdfObj");
