    File_write_line(f, "            if (f is PdfName) filters.Add(((PdfName)f).Raw);");
    File_write_line(f, "            else if (f is PdfArr) foreach (PdfObj o in ((PdfArr)f).Items) { PdfName n = doc.Resolve(o) as PdfName; if (n != null) filters.Add(n.Raw); }");
    File_write_line(f, "            if (s.Dict.Get(\"DecodeParms\") != null && !(doc.Resolve(s.Dict.Get(\"DecodeParms\")) is PdfNull))");
