    File_write_line(f, "            {");
    File_write_line(f, "                if (name == \"FlateDecode\" || name == \"Fl\") d = Decode(d);");
    File_write_line(f, "                else return null;");
    File_write_line(f, "            }");
    File_write_line(f, "            return d;");
