    File_write_line(f, "        public static int IndexOf(byte[] b, string s, int from)");
    File_write_line(f, "        {");
    File_write_line(f, "            byte f = (byte)s[0];");
    File_write_line(f, "            int last = b.Length - s.Length;");
    File_write_line(f, "            for (int i = Math.Max(0, from); i <= last; i++)");
    File_write_line(f, "            {");
    File_write_line(f, "                if (b[i] != f) continue;");
    File_write_line(f, "                int k = 1;");
    File_write_line(f, "                while (k < s.Length && b[i + k] == (byte)s[k]) k++;");
    File_write_line(f, "                if (k == s.Length) return i;");
    File_write_line(f, "            }");
    File_write_line(f, "            return -1;");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        void CollectPages(PdfDict node, PdfDict inherited, int depth)");
    File_write_line(f, "        {");
    File_write_line(f, "            if (node == null || depth > 64) return;");
    File_write_line(f, "            PdfDict inh = new PdfDict();");
    File_write_line(f, "            if (inherited != null) foreach (string k in inherited.Keys) inh.Set(k, inherited.Get(k));");
    File_write_line(f, "            foreach (string k in new string[] { \"Resources\", \"MediaBox\", \"CropBox\", \"Rotate\" })");
    File_write_line(f, "                if (node.Get(k) != null) inh.Set(k, node.Get(k));");
    File_write_line(f, "            if (node.NameOf(\"Type\") == \"Pages\" || node.Get(\"Kids\") != null)");
    File_write_line(f, "            {");
    File_write_line(f, "                PdfArr kids = Resolve(node.Get(\"Kids\")) as PdfArr;");
    File_write_line(f, "                if (kids == null) return;");
    File_write_line(f, "                foreach (PdfObj k in kids.Items) CollectPages(Resolve(k) as PdfDict, inh, depth + 1);");
    File_write_line(f, "                return;");
    File_write_line(f, "            }");
    File_write_line(f, "            PdfDict page = new PdfDict();");
    File_write_line(f, "            foreach (string k in node.Keys) page.Set(k, node.Get(k));");
    File_write_line(f, "            foreach (string k in inh.Keys) if (page.Get(k) == null) page.Set(k, inh.Get(k));");
    File_write_line(f, "            Pages.Add(page);");
    File_write_line(f, "        }");
