    File_write_line(f, "");
    File_write_line(f, "        // Deep-copies o from src into this writer, renumbering references through map.");
    File_write_line(f, "        public PdfObj Import(PdfDoc src, PdfObj o, Dictionary<int, int> map)");
    File_write_line(f, "        {");
    File_write_line(f, "            PdfRef r = o as PdfRef;");
    File_write_line(f, "            if (r != null)");
    File_write_line(f, "            {");
    File_write_line(f, "                int nn;");
    File_write_line(f, "                if (map.TryGetValue(r.Num, out nn)) return new PdfRef(nn, 0);");
    File_write_line(f, "                PdfObj target = src.Resolve(r);");
    File_write_line(f, "                PdfStream ts = target as PdfStream;");
    File_write_line(f, "                string key = null;");
    File_write_line(f, "                if (ts != null && !HasRefs(ts.Dict, \"Length\"))");
    File_write_line(f, "                {");
    File_write_line(f, "                    key = HashStream(ts);");
    File_write_line(f, "                    int existing;");
    File_write_line(f, "                    if (streamHash.TryGetValue(key, out existing))");
    File_write_line(f, "                    {");
    File_write_line(f, "                        map[r.Num] = existing;");
    File_write_line(f, "                        DedupedStreams++;");
    File_write_line(f, "                        DedupedBytes += ts.Data.Length;");
    File_write_line(f, "                        return new PdfRef(existing, 0);");
    File_write_line(f, "                    }");
    File_write_line(f, "                }");
    File_write_line(f, "                int num = Reserve();");
