    File_write_line(f, "                PdfDict d = (PdfDict)o;");
    File_write_line(f, "                foreach (string k in d.Keys) if (k != skipKey && HasRefs(d.Get(k), null)) return true;");
    File_write_line(f, "            }");
    File_write_line(f, "            if (o is PdfArr) foreach (PdfObj i in ((PdfArr)o).Items) if (HasRefs(i, null)) return true;");
    File_write_line(f, "            return false;");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        static string HashStream(PdfStream s)");
    File_write_line(f, "        {");
    File_write_line(f, "            using (SHA1 sha = SHA1.Create())");
    File_write_line(f, "            {");
    File_write_line(f, "                PdfDict d = new PdfDict();");
    File_write_line(f, "                foreach (string k in s.Dict.Keys) if (k != \"Length\") d.Set(k, s.Dict.Get(k));");
    File_write_line(f, "                byte[] head = Serialize(d);");
    File_write_line(f, "                sha.TransformBlock(head, 0, head.Length, null, 0);");
    File_write_line(f, "                sha.TransformFinalBlock(s.Data, 0, s.Data.Length);");
    File_write_line(f, "                return Convert.ToBase64String(sha.Hash) + \":\" + s.Data.Length.ToString(CultureInfo.InvariantCulture);");
    File_write_line(f, "            }");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        // One canonical OCG per layer name across the whole output");
    File_write_line(f, "        public int OcgFor(string name, PdfDict usageTemplate)");
    File_write_line(f, "        {");
    File_write_line(f, "            int n;");
    File_write_line(f, "            if (OcgByName.TryGetValue(name, out n)) return n;");
    File_write_line(f, "            PdfDict g = new PdfDict();");
    File_write_line(f, "            g.Set(\"Type\", new PdfName(\"OCG\"));");
    File_write_line(f, "            g.Set(\"Name\", PdfStr.FromText(name));");
    File_write_line(f, "            if (usageTemplate != null) g.Set(\"Usage\", usageTemplate);");
    File_write_line(f, "            n = Add(g);");
    File_write_line(f, "            OcgByName[name] = n;");
