    File_write_line(f, "                    return r == null ? null : r.Raw;");
    File_write_line(f, "                }");
    File_write_line(f, "            }");
    File_write_line(f, "            return null;");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        // True when the stream contains any painting operator");
