    File_write_line(f, "        {");
    File_write_line(f, "            PdfParser p = new PdfParser(data, 0);");
    File_write_line(f, "            while (!p.AtEnd)");
    File_write_line(f, "            {");
    File_write_line(f, "                int before = p.Pos;");
    File_write_line(f, "                PdfKeyword k = p.ReadObject() as PdfKeyword;");
    File_write_line(f, "                if (p.Pos == before) { p.Pos++; continue; }");
    File_write_line(f, "                if (k == null) continue;");
    File_write_line(f, "                switch (k.Word)");
