    File_write_line(f, "                    case \"S\": case \"s\": case \"f\": case \"F\": case \"f*\": case \"B\": case \"B*\": case \"b\": case \"b*\":");
    File_write_line(f, "                    case \"Tj\": case \"TJ\": case \"'\": case \"\\\"\": case \"Do\": case \"sh\": case \"BI\":");
    File_write_line(f, "                        return true;");
