    File_write_line(f, "        {");
    File_write_line(f, "            Dictionary<string, double[]> res = new Dictionary<string, double[]>();");
    File_write_line(f, "            Stack<double[]> stack = new Stack<double[]>();");
    File_write_line(f, "            double[] ctm = { 1, 0, 0, 1, 0, 0 };");
    File_write_line(f, "            List<PdfObj> ops = new List<PdfObj>();");
    File_write_line(f, "            PdfParser p = new PdfParser(data, 0);");
    File_write_line(f, "            while (!p.AtEnd)");
