    File_write_line(f, "                if (p.Pos == before) { p.Pos++; continue; }");
    File_write_line(f, "                PdfKeyword k = o as PdfKeyword;");
    File_write_line(f, "                if (k == null) { ops.Add(o); continue; }");
    File_write_line(f, "                switch (k.Word)");
    File_write_line(f, "                {");
    File_write_line(f, "                    case \"q\": stack.Push((double[])ctm.Clone()); break;");
    File_write_line(f, "                    case \"Q\": if (stack.Count > 0) ctm = stack.Pop(); break;");
    File_write_line(f, "                    case \"cm\":");
    File_write_line(f, "                        if (ops.Count >= 6)");
    File_write_line(f, "                        {");
    File_write_line(f, "                            double[] m = new double[6];");
    File_write_line(f, "                            bool ok = true;");
    File_write_line(f, "                            for (int i = 0; i < 6; i++)");
    File_write_line(f, "                            {");
