    File_write_line(f, "                            }");
    File_write_line(f, "                        }");
    File_write_line(f, "                        break;");
    File_write_line(f, "                    case \"BI\":");
    File_write_line(f, "                        int id = PdfDoc.IndexOf(data, \"ID\", p.Pos);");
    File_write_line(f, "                        int ei = id < 0 ? -1 : PdfDoc.IndexOf(data, \"EI\", id + 3);");
