    File_write_line(f, "                        break;");
    File_write_line(f, "                }");
    File_write_line(f, "                ops.Clear();");
    File_write_line(f, "            }");
    File_write_line(f, "            return res;");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        static double[] Mul(double[] a, double[] b)");
    File_write_line(f, "        {");
    File_write_line(f, "            return new double[] {");
    File_write_line(f, "                a[0] * b[0] + a[1] * b[2], a[0] * b[1] + a[1] * b[3],");
