    File_write_line(f, "    }");
    File_write_line(f, "");
    File_write_line(f, "    // =================================================================");
    File_write_line(f, "    // Content index: a 12d page cut into its operations, each drawing");
    File_write_line(f, "    // with its extent on the page, so a sheet can take just what lies in");
    File_write_line(f, "    // its window.  State operators (colours, widths, fonts, layers, q/Q)");
    File_write_line(f, "    // always go through; a drawing that is left out still hands on any");
    File_write_line(f, "    // state change made inside it.");
    File_write_line(f, "    // =================================================================");
    File_write_line(f, "    public sealed class ContentIndex");
    File_write_line(f, "    {");
    File_write_line(f, "        public const int STATE = 0, DRAW = 1, PUSH = 2, POP = 3;");
    File_write_line(f, "");
    File_write_line(f, "        public sealed class Op");
    File_write_line(f, "        {");
    File_write_line(f, "            public int Kind, Start, Len, Stream;");
    File_write_line(f, "            public double X0 = double.MaxValue, Y0 = double.MaxValue, X1 = double.MinValue, Y1 = double.MinValue;");
    File_write_line(f, "            public List<int[]> Keep;   // state operators inside a drawing: {start, length}");
    File_write_line(f, "");
    File_write_line(f, "            public void Add(double[] m, double x, double y)");
    File_write_line(f, "            {");
    File_write_line(f, "                double px = m[0] * x + m[2] * y + m[4], py = m[1] * x + m[3] * y + m[5];");
    File_write_line(f, "                if (px < X0) X0 = px; if (px > X1) X1 = px;");
    File_write_line(f, "                if (py < Y0) Y0 = py; if (py > Y1) Y1 = py;");
    File_write_line(f, "            }");
    File_write_line(f, "");
    File_write_line(f, "            public void Grow(double d) { if (X0 <= X1) { X0 -= d; Y0 -= d; X1 += d; Y1 += d; } }");
    File_write_line(f, "        }");
    File_write_line(f, "");
    File_write_line(f, "        public byte[] Data;");
    File_write_line(f, "        public readonly List<Op> Ops = new List<Op>();");
    File_write_line(f, "        public readonly List<string> Layers = new List<string>();   // layer of each content stream, null if none");
    File_write_line(f, "        public int Streams { get { return Layers.Count; } }");
    File_write_line(f, "");
    File_write_line(f, "        public static ContentIndex Build(PdfDoc doc, PdfDict page)");
    File_write_line(f, "        {");
